contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call with an amount parameter; when amount == TICKET_AMOUNT (10) the call must not revert
    // and the resulting pot must be either increased by amount or reset to 0.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read observable before-values
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        uint balance_before = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint balance_after = address(c).balance;

        // The rule: if caller sends exactly the ticket price (10) the call must not revert,
        // and the pot afterward is either pot_before + amount or 0.
        // (Also ensure the contract balance changes consistently with pot change.)
        assert(
            (amount == 10 && reverted == false && (pot_after == pot_before + amount || pot_after == 0)) ||
            // If amount != 10, we make no guarantee about revert; but still the pot must be one of these two values
            // when a non-reverting call happened. To keep the assertion general, allow either revert or the same pot outcomes.
            (amount != 10 && (reverted == true || pot_after == pot_before + amount || pot_after == 0))
        );
    }

    receive() external payable {}
}

